const base = env.get('API_BASE');
const token = env.get('OUTBOX_TOKEN');
// ไม่ได้ตั้งกุญแจ = ไม่ต้องยิงให้เปลืองและให้ log ฝั่งกล่องรก
if (!token) { node.status({fill:'grey',shape:'ring',text:'ยังไม่ได้ตั้ง OUTBOX_TOKEN'}); return null; }
msg.url = `${base}/api/control/outbox?limit=10`;
msg.method = 'GET';
msg.headers = { 'x-outbox-token': token };
return msg;

if (msg.statusCode !== 200) {
  node.status({fill:'red',shape:'dot',text:`กล่องตอบ ${msg.statusCode}`});
  node.warn(`ขอคำสั่งไม่สำเร็จ: ${msg.statusCode} ${JSON.stringify(msg.payload)}`);
  return null;
}
const list = msg.payload?.commands ?? [];
node.status({fill: list.length ? 'blue' : 'green', shape:'dot',
             text: list.length ? `ค้าง ${list.length}` : 'ไม่มีคำสั่งค้าง'});
if (list.length === 0) return null;
// ★ ส่งทีละรายการ **ตามลำดับเดิม** — API เรียงเก่าก่อนใหม่มาให้แล้ว
//   สลับลำดับเมื่อไร สั่ง 'เปิด' แล้ว 'ปิด' จะกลับด้านโดยไม่มีใครรู้
return [list.map((c) => ({ payload: c }))];

// ═══════════════════════════════════════════════════════════════
//  ★★★ ตรงนี้คือส่วนที่ต้องเติมเอง และห้ามเดา ★★★
//
//  เดาผิดแล้วโชคดีคือไม่มีอะไรเกิดขึ้น
//  เดาผิดแล้วโชคร้ายคือพัดลมในโรงเรือนจริงหยุดหมุน
//
//  ต้องได้สเปกจากเจ้าของระบบสภาพแวดล้อมก่อนว่า
//    · topic ที่ PLC ฟังอยู่คืออะไร
//    · payload หน้าตาแบบไหน (JSON? ตัวเลขดิบ? สตริง?)
//    · ความเร็วพัดลมใช้หน่วยอะไร (Hz? เปอร์เซ็นต์? ระดับ 1-5?)
// ═══════════════════════════════════════════════════════════════
const c = msg.payload;   // {id, barnKey, deviceKind, deviceId, remoteAddr, action, hz}

const MAPPED = false;    // ← เปลี่ยนเป็น true เมื่อเติมด้านล่างเสร็จแล้ว

if (!MAPPED) {
  // ★ ยังไม่ได้ตั้งค่า = **ไม่ส่งอะไรออกไป** แล้วรายงานกลับว่าส่งไม่สำเร็จ
  //   ปลอดภัยกว่าการส่งของมั่ว ๆ ไปให้ PLC และดีกว่าเงียบไปเฉย ๆ
  node.status({fill:'yellow',shape:'ring',text:'ยังไม่ได้เติมตัวแปลง'});
  return [null, { payload: { id: c.id, ok: false,
           detail: 'Node-RED ยังไม่ได้ตั้งค่าตัวแปลงไปเป็นภาษา PLC' } }];
}

// ---- เติมตรงนี้ ----------------------------------------------
// ตัวอย่างโครง (ตัวเลขและชื่อ topic เป็นของสมมติ ห้ามใช้จริงก่อนยืนยัน)
//   msg.topic = c.remoteAddr || `farm/kpp/${c.barnKey}/${c.deviceId}`;
//   msg.payload = { cmd: c.action, hz: c.hz };
// --------------------------------------------------------------

msg._cmdId = c.id;       // เก็บไว้ตอบกลับ
node.status({fill:'blue',shape:'dot',text:`ส่ง ${c.deviceId} ${c.action}`});
return [msg, null];

const base = env.get('API_BASE');
const token = env.get('OUTBOX_TOKEN');
const { id, ...body } = msg.payload;
msg.url = `${base}/api/control/outbox/${id}/ack`;
msg.method = 'POST';
msg.headers = { 'x-outbox-token': token, 'content-type': 'application/json' };
msg.payload = body;
return msg;
